        for (int j = len - 1; j >= 0; j--) {
            arr[j] = code % base;
            code /= base;
        }
    }

    void run() {
        int n = in.nextInt();
        int m = in.nextInt();
        if (n < m) {
            int temp = n; n = m; m = temp;
        }
        int totalStates = 1;
        for (int j = 0; j < m; j++) totalStates *= 3;
        int[] dp = new int[totalStates];
        int[] nextDp = new int[totalStates];
        int[] stateA = new int[m];
        int[] stateB = new int[m];
        Arrays.fill(stateA, 1);
        Arrays.fill(dp, -1);
        dp[encode(stateA, m)] = 0;
        while (n-- > 0) {
