                            countOnes++;
                        }
                    }
                    for (int j = 0; j < m; j++) {
                        if (stateB[j] == 0 && (stateA[j] == 2 || (j > 0 && stateB[j - 1] == 2) || (j + 1 < m && stateB[j + 1] == 2))) {
                            stateB[j] = 1;
                        }
                    }
                    int newStateIdx = encode(stateB, m);
                    nextDp[newStateIdx] = Math.max(nextDp[newStateIdx], dp[stateIdx] + m - countOnes);
                }
            }
            int[] temp = dp; dp = nextDp; nextDp = temp;
        }
        int maxResult = 0;
