    vector<int> nextDp(totalStates, -1);
    vector<int> stateA(m);
    vector<int> stateB(m);
    fill(stateA.begin(), stateA.end(), 1);
    fill(dp.begin(), dp.end(), -1);
    dp[encode(stateA, m)] = 0;
    while (n-- > 0) {
        fill(nextDp.begin(), nextDp.end(), -1);
        for (int stateIdx = 0; stateIdx < totalStates; stateIdx++) {
            if (dp[stateIdx] < 0) continue;
            decode(stateA, m, stateIdx, 3);
            for (int mask = 0; mask < (1 << m); mask++) {
                decode(stateB, m, mask, 2);
                bool invalid = false;
                for (int j = 0; j < m; j++) {
                    if (stateA[j] == 0 && stateB[j] == 0) {
                        invalid = true;
                        break;
                    }
